//! Button copied by `tesso add button`.
//!
//! Fusor component tags do not accept `on:click` (that attribute is only for
//! native elements, and the name is not a snake_case input). The page passes
//! an `on_press` callback instead. `variant` and `size` are static strings.
//! Omit them and they default to `primary` and `md`.
//!
//! Variants: primary, secondary, quiet, danger.
//! Sizes: sm, md, lg.

use std::rc::Rc;

use fusor::prelude::*;

#[derive(FromInputs)]
pub struct Button {
    #[input(default = "primary")]
    variant: &'static str,
    #[input(default = "md")]
    size: &'static str,
    #[input]
    on_press: Rc<dyn Fn()>,
}

impl Button {
    fn press(&self) {
        (self.on_press)();
    }
}

fusor::template!("web/components/button.html");

css.content:
@layer properties, theme, base, components, utilities;

@layer components {
  .tesso-button {
    appearance: none;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.5rem;
    min-height: 2.5rem;
    padding: 0.5rem 1rem;
    border: 1px solid var(--border);
    border-radius: calc(var(--radius) - 2px);
    background: var(--background);
    color: var(--foreground);
    font: inherit;
    cursor: pointer;
  }

  .tesso-button:focus {
    outline: none;
  }

  .tesso-button:focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
  }

  .tesso-button:disabled {
    opacity: 0.55;
    cursor: not-allowed;
  }

  .tesso-button-primary {
    background: var(--primary);
    color: var(--primary-foreground);
    border-color: transparent;
  }

  .tesso-button-secondary {
    background: var(--secondary);
    color: var(--secondary-foreground);
    border-color: var(--border);
  }

  .tesso-button-quiet {
    background: var(--muted);
    color: var(--foreground);
    border-color: transparent;
  }

  /* There's no --destructive-foreground; the danger button uses --primary-foreground for its text. */
  .tesso-button-danger {
    background: var(--destructive);
    color: var(--primary-foreground);
    border-color: transparent;
  }

  .tesso-button-sm {
    min-height: 2rem;
    padding: 0.25rem 0.75rem;
    font-size: 0.75rem;
  }

  .tesso-button-lg {
    min-height: 3rem;
    padding: 0.75rem 1.25rem;
    font-size: 1rem;
  }
}
